refentry.refsect1:
&reftitle.description;
booldio_tcsetattr resourcefd arrayoptions
dio_tcsetattr imposta gli attributi del terminale e la velocità in baud del descrittore aperto fd.

  &reftitle.examples;

   Impostazione della velocità in baud su una porta seriale


<?php

$fd = dio_open('/dev/ttyS0', O_RDWR | O_NOCTTY | O_NONBLOCK);

dio_fcntl($fd, F_SETFL, O_SYNC);

dio_tcsetattr($fd, array(
    'baud' => 9600,
    'bits' => 8,
    'stop'  => 1,
    'parity' => 0
)); 

while (true) {
    $data = dio_read($fd, 256);
    if ($data !== null && $data !== '') {
        echo $data;
    }
} 

?>
